package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Full-height right-hand controls with a still draft preview; no preference writes while stepping. */
final class AppearanceDrawer {
    static void show(Activity a){if(!ProductFeatures.allowEdit(a,()->show(a)))return;Config cfg=Config.load(a);String profile=ProfileStore.id();android.content.SharedPreferences prefs=ProfileStore.preferences(a);Map<String,?> before=prefs.getAll();
        Map<String,Object> initial=new HashMap<>();String look=ExperienceChoice.saved(a);String pos=PlacementSession.selected(a);initial.put(AppPlacement.KEY,AppPlacement.valid(pos==null?"":pos)?pos:ExperiencePolicy.defaultPosition(look));initial.put(IconSizePolicy.KEY,IconSizes.current(a));initial.put(TileSpacing.CHOICE,cfg.tileGap);initial.put(HomePolish.NAMES,prefs.getInt(HomePolish.NAMES,0));initial.put("animations",cfg.animations);initial.put("wallpaper_dim_choice",cfg.wallpaperDim);initial.put("reduced_motion_choice",cfg.reducedMotion);AppearanceDraft draft=new AppearanceDraft(initial);
        Dialog dialog=new Dialog(a);LinearLayout page=new LinearLayout(a);page.setBackgroundColor(0xff0d1724);page.setPadding(dp(a,20),dp(a,20),dp(a,20),dp(a,20));LinearLayout previewBox=new LinearLayout(a);previewBox.setOrientation(LinearLayout.VERTICAL);previewBox.setGravity(Gravity.CENTER);page.addView(previewBox,new LinearLayout.LayoutParams(0,-1,1));
        TextView caption=FreedomUi.text(a,"Appearance preview",24);previewBox.addView(caption);HomeMiniPreview preview=new HomeMiniPreview(a,SettingsTypography.regular(a));LinearLayout.LayoutParams image=new LinearLayout.LayoutParams(dp(a,338),dp(a,190));image.topMargin=dp(a,18);previewBox.addView(preview,image);previewBox.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int width=Math.min(dp(a,480),r-l),height=width*9/16;if(preview.getLayoutParams().width!=width||preview.getLayoutParams().height!=height){LinearLayout.LayoutParams size=(LinearLayout.LayoutParams)preview.getLayoutParams();size.width=width;size.height=height;preview.setLayoutParams(size);}});previewBox.addView(FreedomUi.text(a,"Still illustration using your current wallpaper.\nChanges are saved only with Apply.",15));
        LinearLayout panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(a,22),0,0,0);page.addView(panel,new LinearLayout.LayoutParams(dp(a,346),-1));panel.addView(FreedomUi.text(a,"Make it yours",26));panel.addView(FreedomUi.text(a,"↑ ↓ Choose · ← → Adjust · Back cancels",14));
        ScrollView scroll=new ScrollView(a);LinearLayout rows=new LinearLayout(a);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));String[] labels={"App position","Icon size","Extra spacing","App names","Animations","Wallpaper dim","Reduced motion · still fallback"};TextView[] controls=new TextView[labels.length];
        Runnable refresh=()->{preview.preset(draft.preview(look));for(int i=0;i<controls.length;i++)if(controls[i]!=null){Object value=draft.get(i);String s=i==1?IconSizePolicy.label((String)value):i==3?new String[]{"Theme","All apps","Selected app","Hidden"}[(Integer)value]:value instanceof Boolean?(Boolean)value?"On":"Off":value.toString();controls[i].setText(labels[i]+"\n‹  "+s+(i==2?" dp":i==5?"%":"")+"  ›");}};
        for(int i=0;i<labels.length;i++){final int at=i;TextView row=FreedomUi.action(a,rows,labels[i],()->{draft.step(at,1);refresh.run();});controls[i]=row;row.setContentDescription(labels[i]+", Left or Right to adjust");row.setOnKeyListener((v,k,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT)){draft.step(at,k==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1);refresh.run();return true;}return false;});}
        FreedomUi.action(a,rows,"Home style · "+ExperiencePolicy.name(look),()->{if(draft.changes().isEmpty()){dialog.dismiss();ExperienceChoice.show(a);}else Toast.makeText(a,"Apply or cancel this draft before changing Home style",Toast.LENGTH_LONG).show();});
        LinearLayout footer=new LinearLayout(a);footer.setOrientation(LinearLayout.VERTICAL);panel.addView(footer);FreedomUi.action(a,footer,"Cancel",dialog::dismiss);FreedomUi.action(a,footer,"Apply",()->{try{if(!profile.equals(ProfileStore.id())||!before.equals(prefs.getAll())||!ProductFeatures.layoutEditable(a))throw new IllegalStateException("Home changed. Reopen appearance.");Map<String,Object> changes=draft.changes();if(changes.isEmpty()){dialog.dismiss();return;}SetupValues.validate(changes);ProductFeatures.beforeChange(a,"Apply appearance drawer");changes.put(Config.SETTINGS_REVISION_KEY,prefs.getLong(Config.SETTINGS_REVISION_KEY,0)+1);if(!SetupValues.commit(prefs,changes))throw new IllegalStateException("Could not save; original settings retained");dialog.dismiss();a.recreate();}catch(Exception bad){Toast.makeText(a,bad.getMessage(),Toast.LENGTH_LONG).show();}});
        refresh.run();dialog.setContentView(page);dialog.setOnShowListener(d->controls[0].requestFocus());dialog.show();Window w=dialog.getWindow();if(w!=null){w.setLayout(-1,-1);w.setBackgroundDrawableResource(android.R.color.transparent);}
    }
    private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
    private AppearanceDrawer(){}
}
